    int dy[4] = {0, 1, 0, -1};
    char dc[4] = {'N', 'E', 'S', 'W'};

    int d = 0;
    for (int i = 0; i < 4; i++) {
        if (dc[i] == dir) {
            d = i;
            break;
        }
    }

    while (k--) {
        int nx = x + dx[d];
        int ny = y + dy[d];

        if (nx < 0 || nx >= n || ny < 0 || ny >= m || grid[nx][ny] == '#') {
            d = (d + 1) % 4; // turn right
        } else {
            x = nx;
            y = ny;
        }
    }

    printf("%d %d %c\n", x, y, dc[d]);
    return 0;
