import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        int m = fs.nextInt();
        long k = fs.nextLong();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = fs.next();
            grid[i] = s.toCharArray();
        }

        int r = fs.nextInt() - 1;
        int c = fs.nextInt() - 1;
        String dirStr = fs.next();

        // Directions: N, E, S, W
        int dir = dirIndex(dirStr.charAt(0));
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};
        char[] dirChar = {'N', 'E', 'S', 'W'};

        // State: (r, c, dir)
        // Deterministic transitions, so we can detect cycle.
        Map<Long, Integer> seen = new HashMap<>();
        List<long[]> states = new ArrayList<>();

        int step = 0;
        while (step < k) {
            long key = encode(r, c, dir, m);

            if (seen.containsKey(key)) {
                int start = seen.get(key);
                int cycleLen = step - start;
                long remaining = k - step;
                if (cycleLen > 0) {
                    long skip = remaining / cycleLen;
                    if (skip > 0) {
                        step += (int)(skip * cycleLen);
                        continue;
                    }
                }
            } else {
                seen.put(key, step);
                states.add(new long[]{r, c, dir});
            }

            int nr = r + dr[dir];
            int nc = c + dc[dir];

            if (nr < 0 || nr >= n || nc < 0 || nc >= m || grid[nr][nc] == '#') {
                dir = (dir + 1) % 4;
            } else {
                r = nr;
                c = nc;
            }
            step++;
        }

        System.out.println((r + 1) + " " + (c + 1) + " " + dirChar[dir]);
    }

    static int dirIndex(char ch) {
        if (ch == 'N') return 0;
        if (ch == 'E') return 1;
        if (ch == 'S') return 2;
        return 3; // W
    }

    static long encode(int r, int c, int dir, int m) {
        return (((long) r * m + c) << 2) | dir;
    }
}

